    }
  } else if (opponentScore > playerScore) {
    if (fight.round === fight.totalRounds) endFight('loss');
    else {
      fight.round += 1;
      fight.timer = 180;
      fight.playerHealth = clamp(fight.playerHealth + 18, 0, 100);
      fight.opponentHealth = clamp(fight.opponentHealth + 18, 0, 100);
      fight.playerStamina = 100;
      fight.opponentStamina = 100;
